// The printer panel's own parts: the card pinned above the thread, the cards
// drawn inside it, the row of things to tap, and the card that confirms a
// change to a printer.
//
// Everything here renders host state, in words made on this page
// (printerWords.ts). A tap sends a typed printer action or a tool decision,
// which C++ carries out -- never a change made on this side, and never words
// sent as the person's. A tap the model should know about carries its note,
// which the app records if the tap goes through.

import { memo } from 'react';
import type {
  NetworkPrinterInfo,
  PrinterBlock,
  PrinterCardInfo,
  PrinterChangeConfirm,
  PrinterSessionPayload,
  PrinterSpoolInfo,
  ToolActivityInfo,
} from '../bridge/protocol';
import {
  ADD_LABEL,
  REJECT_LABEL,
  caption,
  cardSubline,
  changeTitle,
  chosenNote,
  factTexts,
  mm,
  networkNote,
  undoText,
  undoneNote,
  type FactText,
} from '../printerWords';

const EM_DASH = '—';

function factClass(fact: FactText): string {
  if (!fact.value) return 'printer-fact-value printer-fact-empty';
  return `printer-fact-value printer-fact-${fact.provenance}`;
}

function factSuffix(fact: FactText): string {
  if (!fact.value) return '';
  if (fact.provenance === 'assumed') return ' · assumed';
  if (fact.provenance === 'changed') return ' · changed';
  return '';
}

function FactRow({ label, fact }: { label: string; fact: FactText }) {
  return (
    <div className="printer-fact">
      <span className="printer-fact-label">{label}</span>
      <span className={factClass(fact)}>
        {fact.swatch && <span className="printer-swatch" style={{ background: fact.swatch }} aria-hidden="true" />}
        {fact.value || EM_DASH}
        {factSuffix(fact)}
      </span>
    </div>
  );
}

// The four facts a printer is, in the order the panel always states them.
export const PrinterPinnedCard = memo(function PrinterPinnedCard({ session }: { session: PrinterSessionPayload }) {
  const facts = factTexts(session.facts);
  return (
    <section className="printer-pinned" aria-label={caption(session)}>
      <p className="printer-pinned-caption">{caption(session)}</p>
      <FactRow label="Printer" fact={facts.printer} />
      <FactRow label="Nozzle" fact={facts.nozzle} />
      <FactRow label="Plate" fact={facts.plate} />
      <FactRow label="Filament" fact={facts.filament} />
    </section>
  );
});

// The camera the panel shows wherever a photo is offered. Inline, like the
// composer's send arrow, because the icon set carries no camera yet.
export function CameraGlyph({ className }: { className: string }) {
  return (
    <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
      <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z" />
      <circle cx="12" cy="13" r="4" />
    </svg>
  );
}

export type PrinterBlockAction = 'network_pick' | 'candidate_pick' | 'undo';

// A tap on a card: the card's id, and the note the model is told if it goes
// through.
export interface PrinterTap {
  blockId?: string;
  note?: string;
}

export interface PrinterBlockProps {
  block: PrinterBlock;
  onAction: (action: PrinterBlockAction, id: string, tap: PrinterTap) => void;
}

// One card in the thread, under the message it belongs to.
export const PrinterBlockView = memo(function PrinterBlockView({ block, onAction }: PrinterBlockProps) {
  if (block.kind === 'tip')
    return (
      <div className="printer-tip">
        <CameraGlyph className="printer-tip-icon" />
        <span>
          <b>Tip:</b> a photo is the fastest way. Use <b>Photo</b> below, or drop a picture of the printer, its nameplate or the box
          into this panel.
        </span>
      </div>
    );

  if (block.kind === 'network') {
    const found = (block.printers ?? []) as NetworkPrinterInfo[];
    return (
      <div className="printer-found">
        <p className="printer-found-caption">FOUND ON YOUR NETWORK</p>
        {found.map((printer) => (
          <div className="printer-row" key={printer.deviceId}>
            <span className={printer.online ? 'printer-dot printer-dot-online' : 'printer-dot'} aria-hidden="true" />
            <span className="printer-row-name">
              {printer.name}
              <small>{printer.serial}</small>
            </span>
            <button
              type="button"
              className="printer-quiet-button"
              onClick={() => onAction('network_pick', printer.deviceId, { note: networkNote(printer) })}
            >
              Use this
            </button>
          </div>
        ))}
      </div>
    );
  }

  if (block.kind === 'undo')
    return (
      <div className="printer-undo">
        <span>{undoText(block)}</span>
        <span aria-hidden="true"> · </span>
        <button type="button" className="printer-link-button" onClick={() => onAction('undo', block.id, { note: undoneNote(block) })}>
          Undo
        </button>
      </div>
    );

  const printers = (block.printers ?? []) as PrinterCardInfo[];
  // A card a newer answer replaced, or the person refused, stays in the
  // thread as a line, so the conversation still reads in order.
  if (block.collapsed)
    return <div className="printer-cards-collapsed">{printers.map((printer) => printer.name).join(' · ')}</div>;

  // One printer is an answer and gets the full card; two or three are a
  // question, and each carries the button that answers it.
  const compact = printers.length > 1;
  return (
    <div className={compact ? 'printer-cards printer-cards-compact' : 'printer-cards'}>
      {printers.map((printer) => (
        <div className="printer-card" key={printer.catalogId}>
          {printer.picture ? (
            <img className="printer-card-picture" src={printer.picture} alt="" />
          ) : (
            <span className="printer-card-picture printer-card-picture-empty" aria-hidden="true" />
          )}
          <span className="printer-card-name">
            {printer.name}
            {cardSubline(printer) && <small>{cardSubline(printer)}</small>}
          </span>
          {compact && (
            <button
              type="button"
              className="printer-quiet-button"
              onClick={() => onAction('candidate_pick', printer.catalogId, { blockId: block.id, note: chosenNote(printer) })}
            >
              This one
            </button>
          )}
        </div>
      ))}
    </div>
  );
});

// The code a Bambu printer shows under Settings > Network. It goes with Add
// to the app, which connects the printer; it is never part of the chat.
export function PrinterAccessCode({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  return (
    <input
      className="printer-access-code"
      type="text"
      autoComplete="off"
      spellCheck={false}
      maxLength={32}
      aria-label="Access code"
      placeholder="access code, optional"
      value={value}
      onChange={(event) => onChange(event.target.value)}
    />
  );
}

export interface ChipRowProps {
  canAdd: boolean;
  disabled: boolean;
  onAdd: () => void;
  onReject: () => void;
}

// What the person can do with the printer on the card. Both act natively;
// adding leads, because the tap is the approval.
export const PrinterChipRow = memo(function PrinterChipRow({ canAdd, disabled, onAdd, onReject }: ChipRowProps) {
  if (!canAdd) return null;
  return (
    <div className="printer-chips">
      <button type="button" className="printer-chip printer-chip-primary" disabled={disabled} onClick={onAdd}>
        {ADD_LABEL}
      </button>
      <button type="button" className="printer-chip printer-chip-plain" disabled={disabled} onClick={onReject}>
        {REJECT_LABEL}
      </button>
    </div>
  );
});

function SpoolList({ spools }: { spools: PrinterSpoolInfo[] }) {
  if (spools.length === 0) return <span className="printer-change-none">none</span>;
  return (
    <ul className="printer-change-spools">
      {spools.map((spool, index) => (
        <li key={`${spool.name}-${index}`}>
          {spool.colour && <span className="printer-swatch" style={{ background: spool.colour }} aria-hidden="true" />}
          {spool.name}
          {spool.material && spool.material !== spool.name && <small> {spool.material}</small>}
        </li>
      ))}
    </ul>
  );
}

// A change the model worked out from what the person said, stated in words
// before anything is saved: the card is where a misreading is caught.
export function PrinterChangeCard({
  activity,
  onDecision,
}: {
  activity: ToolActivityInfo;
  onDecision: (actionId: string, decision: 'approve' | 'reject') => void;
}) {
  const args = activity.arguments as { nozzle?: number; spools?: PrinterSpoolInfo[]; confirm?: PrinterChangeConfirm };
  const confirm = args.confirm;
  const printer = confirm?.printer ?? 'this printer';
  const nozzle = args.nozzle !== undefined && confirm?.before.nozzle !== undefined;
  const spools = args.spools !== undefined && confirm?.before.spools !== undefined;
  const keep = nozzle && !spools ? `Keep ${mm(confirm!.before.nozzle!)}` : 'Keep as it is';
  const set = nozzle && !spools ? `Set ${mm(args.nozzle!)}` : spools && !nozzle ? 'Set these spools' : 'Set both';

  return (
    <div className={`printer-change state-${activity.state}`} data-testid={`tool-${activity.actionId}`}>
      <div className="printer-change-title">{changeTitle(nozzle, spools)}</div>
      {nozzle && (
        <>
          <div className="printer-change-line">
            {mm(confirm!.before.nozzle!)} → <b>{mm(args.nozzle!)}</b> on {printer}
          </div>
          <div className="printer-change-note">Every project that uses this printer slices for {mm(args.nozzle!)}.</div>
        </>
      )}
      {spools && (
        <div className="printer-change-line printer-change-spool-diff">
          <div>
            <small>Now on {printer}</small>
            <SpoolList spools={confirm!.before.spools!} />
          </div>
          <span aria-hidden="true">→</span>
          <div>
            <small>After</small>
            <SpoolList spools={args.spools!} />
          </div>
        </div>
      )}
      {activity.state === 'pending' && (
        <div className="printer-change-actions">
          <button type="button" className="printer-chip printer-chip-plain" onClick={() => onDecision(activity.actionId, 'reject')}>
            {keep}
          </button>
          <button
            type="button"
            className="printer-chip printer-chip-primary"
            onClick={() => onDecision(activity.actionId, 'approve')}
          >
            {set}
          </button>
        </div>
      )}
      {activity.state === 'rejected' && <div className="printer-change-state">Kept as it was</div>}
      {(activity.state === 'approved' || activity.state === 'running') && <div className="printer-change-state">Saving…</div>}
      {activity.state === 'failed' && <div className="tool-error">{activity.error?.message ?? 'The change was not saved.'}</div>}
    </div>
  );
}
// The page in printer-panel mode: the same thread and composer as the docked
// panel, with the printer session's header, pinned card and chips around
// them. What it sends back is a typed printer action, a tool decision, or
// what the person typed -- never a tap dressed up as the person's words.

import { act, render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { beforeEach, describe, expect, it } from 'vitest';
import { App } from './App';
import { PROTOCOL_NAME, PROTOCOL_VERSION } from './bridge/protocol';
import type { Envelope, PrinterSessionPayload, StatePayload, ToolActivityInfo, WorkspaceContext } from './bridge/protocol';

const context: WorkspaceContext = {
  sessionId: '1',
  revision: 1,
  projectName: 'Garage bracket',
  printer: { preset: 'Bambu Lab A1 mini 0.4 nozzle', process: 'Standard', plateType: 'Textured PEI Plate' },
  filaments: [],
  plates: [],
  presetDeltas: [],
} as unknown as WorkspaceContext;

class MockHost {
  received: Envelope[] = [];

  transport = {
    post: (json: string) => {
      this.received.push(JSON.parse(json));
    },
  };

  deliver(type: string, payload: unknown): void {
    act(() => {
      window.__jusprinBridge!.deliver({
        protocol: PROTOCOL_NAME,
        version: PROTOCOL_VERSION,
        id: `h-${this.received.length}-${type}`,
        type,
        payload,
      } as Envelope);
    });
  }

  lastOfType(type: string): Envelope | undefined {
    return [...this.received].reverse().find((envelope) => envelope.type === type);
  }
}

function session(overrides: Partial<PrinterSessionPayload> = {}): PrinterSessionPayload {
  return {
    mode: 'add',
    facts: {
      printer: { name: 'Bambu Lab A1 mini', provenance: 'settled' },
      nozzle: { size: 0.4, provenance: 'assumed' },
      plate: { name: 'Textured PEI Plate', provenance: 'assumed' },
      filament: { preset: 'Bambu PLA Basic @BBL A1M', ams: '', spools: [], provenance: 'assumed' },
    },
    blocks: [],
    canAdd: true,
    ...overrides,
  };
}

function state(overrides: Partial<StatePayload> = {}): StatePayload {
  return {
    agent: { status: 'ready' },
    appearance: 'light',
    conversations: [{ id: 'conv-1', title: 'Printer', createdAt: 't' }],
    activeConversationId: 'conv-1',
    conversation: [{ id: 'm-1', role: 'assistant', state: 'complete', text: 'What printer do you have?', seq: 1 }],
    streamingMessageId: null,
    toolActivities: [],
    builds: [],
    exportedCopies: [],
    physicalPrints: [],
    draft: '',
    context,
    session: session(),
    ...overrides,
  } as unknown as StatePayload;
}

function open(payload: StatePayload = state()): MockHost {
  const host = new MockHost();
  render(<App getTransport={() => host.transport} printerPanel />);
  host.deliver('hello_ack', { version: PROTOCOL_VERSION });
  host.deliver('state', payload);
  return host;
}

describe('the printer panel page', () => {
  beforeEach(() => {
    document.body.innerHTML = '';
  });

  it('writes the model its instructions, and again only when the words change', () => {
    const host = open(state({ session: session({ context: { printers: [['BBL/Bambu Lab A1 mini', 'Bambu Lab A1 mini', '180 × 180 × 180 mm']], network: [] } }) }));
    const sent = () => host.received.filter((envelope) => envelope.type === 'printer_instructions');
    expect(sent()).toHaveLength(1);
    expect((sent()[0].payload as { text: string }).text).toContain('BBL/Bambu Lab A1 mini | Bambu Lab A1 mini | 180 × 180 × 180 mm');

    // A new card changes nothing the model is told.
    host.deliver('printer_session', session({ canAdd: false, context: { printers: [['BBL/Bambu Lab A1 mini', 'Bambu Lab A1 mini', '180 × 180 × 180 mm']], network: [] } }));
    expect(sent()).toHaveLength(1);

    // A changed printer does.
    host.deliver(
      'printer_session',
      session({
        mode: 'change',
        canAdd: false,
        context: {
          printer: { name: 'Lab Printer', model: '', nozzle: 0.6, nozzles: [0.4, 0.6], spools: [], connected: false },
        },
      }),
    );
    expect(sent()).toHaveLength(2);
    expect((sent()[1].payload as { text: string }).text).toContain('Nozzle: 0.6 mm');
  });

  it('names where back leads, not the printer it is about', async () => {
    // canAdd: false -- this test is about which action the tap sends, not
    // about F7's leave-confirmation, so it uses the nothing-to-lose case.
    const host = open(state({ session: session({ canAdd: false }) }));
    expect(screen.getByRole('heading', { name: 'Printers' })).toBeInTheDocument();

    await userEvent.click(screen.getByRole('button', { name: 'Back to printers' }));
    expect(host.lastOfType('printer_action')!.payload).toMatchObject({ action: 'close' });
  });

  it('keeps the way out to OrcaSlicer’s own screens', async () => {
    const host = open(state({ session: session({ canAdd: false }) }));
    await userEvent.click(screen.getByRole('button', { name: 'Set it up myself' }));
    expect(host.lastOfType('printer_action')!.payload).toMatchObject({ action: 'manual_setup' });
  });

  // WP10 (F10), corrected by F7 on printer-panel-review-fixes-handoff.md:
  // message count alone caught a saved, applied Change too -- the panel
  // stays open after a printer_change succeeds, and nothing said there was
  // actually going to be lost. Gate on unsaved work instead: an Add
  // proposal still on its card, a Change still waiting on its own approval
  // card, a staged photo, or a draft.
  describe('leaving a conversation that holds unsaved work', () => {
    const withProposal = () =>
      open(
        state({
          conversation: [
            { id: 'm-1', role: 'assistant', state: 'complete', text: 'What printer do you have?', attempt: 1 },
            { id: 'm-2', role: 'user', state: 'complete', text: 'bambu a1 mini', attempt: 1 },
          ],
          session: session({ canAdd: true }),
        }),
      );

    it('asks before "‹ Printers" discards an Add proposal, and does nothing until answered', async () => {
      const host = withProposal();
      await userEvent.click(screen.getByRole('button', { name: 'Back to printers' }));
      expect(screen.getByRole('dialog', { name: 'Leave this conversation?' })).toBeInTheDocument();
      expect(host.received.some((envelope) => envelope.type === 'printer_action')).toBe(false);
    });

    it('leaves on confirmation, and does nothing on cancel', async () => {
      const host = withProposal();
      await userEvent.click(screen.getByRole('button', { name: 'Back to printers' }));
      await userEvent.click(screen.getByRole('button', { name: 'Cancel' }));
      expect(screen.queryByRole('dialog')).toBeNull();
      expect(host.received.some((envelope) => envelope.type === 'printer_action')).toBe(false);

      await userEvent.click(screen.getByRole('button', { name: 'Back to printers' }));
      await userEvent.click(screen.getByRole('button', { name: 'Leave' }));
      expect(host.lastOfType('printer_action')!.payload).toMatchObject({ action: 'close' });
    });

    it('asks before "Set it up myself" discards an Add proposal too', async () => {
      const host = withProposal();
      await userEvent.click(screen.getByRole('button', { name: 'Set it up myself' }));
      expect(screen.getByRole('dialog', { name: 'Leave this conversation?' })).toBeInTheDocument();
      await userEvent.click(screen.getByRole('button', { name: 'Leave' }));
      expect(host.lastOfType('printer_action')!.payload).toMatchObject({ action: 'manual_setup' });
    });

    it('asks before discarding a Change still waiting on its own approval card', async () => {
      const host = open(
        state({
          session: session({ mode: 'change', canAdd: false }),
          toolActivities: [
            {
              actionId: 't-1',
              correlationId: 'm-2',
              server: 'jusprin-native',
              tool: 'printer_change',
              title: 'Change nozzle',
              arguments: { nozzle: 0.6 },
              actionClass: 'mutation',
              requiresApproval: true,
              sessionId: '1',
              expectedRevision: 1,
              state: 'pending',
              progress: { current: 0, total: 1 },
            },
          ],
        }),
      );
      await userEvent.click(screen.getByRole('button', { name: 'Back to printers' }));
      expect(screen.getByRole('dialog', { name: 'Leave this conversation?' })).toBeInTheDocument();
      await userEvent.click(screen.getByRole('button', { name: 'Leave' }));
      expect(host.lastOfType('printer_action')!.payload).toMatchObject({ action: 'close' });
    });

    it('closes at once after a Change already applied -- there is nothing left to lose', async () => {
      const host = open(
        state({
          conversation: [
            { id: 'm-1', role: 'assistant', state: 'complete', text: 'This is the Bambu Lab A1 mini.', attempt: 1 },
            { id: 'm-2', role: 'user', state: 'complete', text: 'I put a 0.6 nozzle on it', attempt: 1 },
            { id: 'm-3', role: 'note', state: 'complete', text: 'Nozzle set to 0.6 mm', attempt: 1 },
          ],
          session: session({ mode: 'change', canAdd: false }),
          toolActivities: [
            {
              actionId: 't-1',
              correlationId: 'm-2',
              server: 'jusprin-native',
              tool: 'printer_change',
              title: 'Change nozzle',
              arguments: { nozzle: 0.6 },
              actionClass: 'mutation',
              requiresApproval: true,
              sessionId: '1',
              expectedRevision: 1,
              state: 'succeeded',
              progress: { current: 1, total: 1 },
            },
          ],
        }),
      );
      await userEvent.click(screen.getByRole('button', { name: 'Back to printers' }));
      expect(screen.queryByRole('dialog')).toBeNull();
      expect(host.lastOfType('printer_action')!.payload).toMatchObject({ action: 'close' });
    });

    // F7 follow-up: state.draft is the main chat's own recovery draft --
    // the backend only ever sets it from a draft_update that panel sends,
    // and the printer panel's composer never did, so state.draft could
    // never answer this check for the printer panel. Past the composer's
    // own debounce, an untouched but typed-into field must still gate.
    it('asks before "‹ Printers" discards an unsent draft, never mind state.draft', async () => {
      const host = open(state({ session: session({ canAdd: false }) }));
      await userEvent.type(screen.getByPlaceholderText(/bambu a1 mini/), 'I put a 0.6 nozzle on it');
      await act(async () => {
        await new Promise((resolve) => setTimeout(resolve, 350));
      });
      await userEvent.click(screen.getByRole('button', { name: 'Back to printers' }));
      expect(screen.getByRole('dialog', { name: 'Leave this conversation?' })).toBeInTheDocument();
      expect(host.received.some((envelope) => envelope.type === 'printer_action')).toBe(false);
    });

    it('asks nothing of a thread that only holds the opening', async () => {
      // The default session() fixture carries canAdd: true (many other
      // tests in this file need a proposed card); this one wants the
      // genuinely-empty case, so it says so explicitly.
      const host = open(state({ session: session({ canAdd: false }) }));
      await userEvent.click(screen.getByRole('button', { name: 'Back to printers' }));
      expect(screen.queryByRole('dialog')).toBeNull();
      expect(host.lastOfType('printer_action')!.payload).toMatchObject({ action: 'close' });
    });
  });

  it('pins the printer’s four facts above the thread', () => {
    open();
    expect(screen.getByText('NEW PRINTER')).toBeInTheDocument();
    expect(screen.getByText(/Bambu Lab A1 mini/)).toBeInTheDocument();
    expect(screen.getByText(/0\.4 mm · assumed/)).toBeInTheDocument();
    // The project's own setup card belongs to the other panel.
    expect(screen.queryByTestId('current-setup')).toBeNull();
  });

  it('shows the agent’s opening in the thread', () => {
    open();
    expect(screen.getByText('What printer do you have?')).toBeInTheDocument();
  });

  it('writes the opening line for an empty thread, once, before the instructions', () => {
    const host = open(state({ conversation: [], session: session({ context: { printers: [], network: [] } }) }));
    const openings = host.received.filter((envelope) => envelope.type === 'printer_opening');
    expect(openings).toHaveLength(1);
    expect((openings[0].payload as { text: string }).text).toMatch(
      /^I'll add your printer so your projects slice for it\. What printer do you have\? Say it any way/,
    );
    const types = host.received.map((envelope) => envelope.type);
    expect(types.indexOf('printer_opening')).toBeLessThan(types.indexOf('printer_instructions'));

    // A later session state does not ask again.
    host.deliver('printer_session', session({ canAdd: false }));
    expect(host.received.filter((envelope) => envelope.type === 'printer_opening')).toHaveLength(1);
  });

  it('names the printer in a Change session’s opening', () => {
    const host = open(
      state({
        conversation: [],
        session: session({
          mode: 'change',
          context: { printer: { name: 'Lab Printer', model: '', nozzle: 0.4, nozzles: [0.4], spools: [], connected: false } },
        }),
      }),
    );
    expect((host.lastOfType('printer_opening')!.payload as { text: string }).text).toMatch(/^This is the Lab Printer\. /);
  });

  it('asks nothing of a thread that already opened', () => {
    const host = open();
    expect(host.lastOfType('printer_opening')).toBeUndefined();
  });

  it('asks a likely answer, and leads the composer with Photo', () => {
    open(state({ session: session({ mode: 'change', canAdd: false }) }));
    expect(screen.getByPlaceholderText('e.g. "I put a 0.6 nozzle on it" or "loaded black PETG"')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Add a photo' })).toBeInTheDocument();
  });

  it('adds the printer and refuses it natively, never as the person speaking', async () => {
    const host = open();

    await userEvent.click(screen.getByRole('button', { name: 'Add this printer' }));
    expect(host.lastOfType('printer_action')!.payload).toEqual({ action: 'add', id: '' });

    // The note the model reads is written here, from the printer on the card.
    await userEvent.click(screen.getByRole('button', { name: 'Not this one' }));
    expect(host.lastOfType('printer_action')!.payload).toEqual({
      action: 'reject',
      id: '',
      note: 'The person said Bambu Lab A1 mini is not their printer.',
    });
    expect(host.lastOfType('user_message')).toBeUndefined();
  });

  it('sends an access code with Add, and never into the chat', async () => {
