const { chromium } = require('C:/Users/guitest/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const { pathToFileURL } = require('node:url');
const path = require('node:path');
const assert = require('node:assert/strict');
(async () => {
  const browser = await chromium.launch({ channel: 'msedge', headless: true });
  const page = await browser.newPage({ viewport: { width: 800, height: 560 } });
  await page.addInitScript(() => {
    let seq = 0;
    window.reviewActions = [];
    window.reviewDeliver = (type, payload) => window.__jusprinBridge.deliver({ protocol: 'jusprin-home-bridge', version: 1, id: `receipt-${++seq}`, type, payload });
    window.wx = { postMessage(json) {
      const e = JSON.parse(json);
      window.reviewActions.push(e);
      if (e.type === 'hello') setTimeout(() => {
        window.reviewDeliver('hello_ack', { version: 1 });
        window.reviewDeliver('state', { appearance: 'light', projects: [], printers: [{
          id: 'review-a1', name: 'Bambu Lab A1 mini', kind: 'named', canOpenSettings: true, canRename: true, canRemove: true,
          state: 'offline', statusText: 'Offline', connectionText: 'Not connected', nozzleText: '0.4 mm nozzle', materialLabel: '', spools: [], canLaunchMonitor: false,
        }] });
        window.reviewDeliver('printer_added', { name: 'Bambu Lab A1 mini', nozzleText: '0.4 mm', nozzleAssumed: true,
          plateText: 'Textured PEI Plate', plateAssumed: true, filamentText: 'PLA', filamentAssumed: true });
      }, 0);
    } };
  });
  await page.goto(pathToFileURL(path.resolve(__dirname, '../resources/jusprin/home/index.html')).href);
  await page.getByRole('button', { name: 'Printer details' }).waitFor();
  await page.locator('.printer-column').screenshot({ path: path.join(__dirname, '10-added-light.png') });
  await page.evaluate(() => window.reviewDeliver('appearance', { appearance: 'dark' }));
  await page.locator('.printer-column').screenshot({ path: path.join(__dirname, '11-added-dark.png') });
  await page.getByRole('button', { name: 'Printer details' }).click();
  assert(await page.evaluate(() => window.reviewActions.some(e => e.type === 'open_printer_settings' && e.payload.id === 'review-a1')));
  console.log('PASS: compact receipt and Printer details route.');
  await browser.close();
})().catch(error => { console.error(error); process.exitCode = 1; });

